-- 0086_sim_concept_to_command: rewrite concept/term quiz steps in the
-- challenge_sim cards into real command-typing steps, so the Simulation
-- drills match the 'gõ lệnh' UI (reported: Windows PrivEsc etc. asked for
-- terms, not commands). Theory rooms with no real commands (Cyber Security
-- 101, Writing Pentest Reports) are intentionally left as concept steps.
-- Idempotent: each UPDATE sets the full corrected payload by card front.

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Windows PrivEsc\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Thu thập thông tin hệ thống Windows: liệt kê các bản vá (hotfix/KB) đã cài để đối chiếu với lỗ hổng đã biết. Gõ lệnh wmic liệt kê hotfix.", "hint": "wmic qfe get Caption,Description,HotFixID,InstalledOn", "patterns": ["wmic\\s+qfe", "systeminfo"], "explanation": "systeminfo + ''wmic qfe'' cho biết OS build và các KB đã vá → đưa vào Windows Exploit Suggester để tìm CVE leo quyền."}, {"prompt": "Tìm service có Unquoted Service Path (đường dẫn chứa khoảng trắng, KHÔNG nằm trong ngoặc kép và không thuộc C:\\Windows). Gõ lệnh wmic lọc.", "hint": "wmic service get name,displayname,pathname,startmode | findstr /i /v \"C:\\Windows\\\\\" | findstr /i /v \"\"\"", "patterns": ["wmic\\s+service\\s+get", "findstr"], "explanation": "Lọc pathname có space mà không có ngoặc kép → Windows có thể chạy nhầm file ở thư mục cha (vd C:\\Program.exe)."}, {"prompt": "Kiểm tra bạn (hoặc nhóm như Authenticated Users) có quyền GHI vào thư mục cha trong đường dẫn service không. Gõ lệnh icacls.", "hint": "icacls \"C:\\Program Files\\Unquoted Path Service\"", "patterns": ["icacls\\s+", "accesschk.*-\\w*w"], "explanation": "icacls / ''accesschk -uwdq'' xem nhóm Everyone/Authenticated Users có (W)/(F); ghi được thì đặt payload theo tên thư mục có space."}, {"prompt": "Xem cấu hình một service (đường dẫn binary, tài khoản chạy) để tìm điểm yếu (quyền ghi binary, DLL thiếu...). Gõ lệnh sc.", "hint": "sc qc <service_name>", "patterns": ["sc\\s+qc", "sc\\s+query"], "explanation": "''sc qc'' hiện BINARY_PATH_NAME và SERVICE_START_NAME (thường LocalSystem) → kiểm tra quyền ghi binary/thư mục để chiếm service."}, {"prompt": "Kiểm tra trạng thái Windows Defender trước khi thả payload leo quyền. Gõ lệnh sc query.", "hint": "sc query windefend", "patterns": ["sc\\s+query\\s+windefend", "get-?mpcomputerstatus"], "explanation": "Nếu Defender đang chạy (RUNNING) thì chọn payload tránh bị bắt; ''Get-MpComputerStatus'' (PowerShell) cho chi tiết realtime protection."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Windows PrivEsc"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Windows PrivEsc';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Linux PrivEsc\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trước khi thử bất kỳ kỹ thuật leo thang đặc quyền nào trên Linux, bước đầu tiên và quan trọng nhất theo phương pháp luận của room này là gì?", "patterns": ["enum", "thu thập thông tin", "liệt kê"], "explanation": "Enumeration (thu thập thông tin hệ thống: kernel, sudo quyền, cron, SUID, tiến trình...) là bước nền tảng để xác định hướng leo thang khả thi, trước khi thử khai thác.", "hint": "Phương pháp luận privesc luôn bắt đầu bằng việc ''liệt kê/thu thập'' trước khi khai thác."}, {"prompt": "Nếu phiên bản kernel của máy Linux mục tiêu quá cũ và có lỗ hổng công khai, công cụ dòng lệnh nào giúp tra cứu nhanh exploit tương ứng, và sau khi tìm được thì cần làm gì với mã nguồn đó trên máy mục tiêu?", "patterns": ["searchsploit"], "explanation": "Searchsploit giúp tra cứu exploit theo phiên bản kernel; sau đó cần chuyển mã nguồn lên máy mục tiêu, biên dịch (compile) rồi chạy để leo quyền root.", "hint": "Công cụ tra cứu Exploit-DB ngay trên terminal."}, {"prompt": "Liệt kê các lệnh bạn được phép chạy bằng sudo (để tra GTFOBins tìm cách thoát ra root). Gõ lệnh.", "hint": "sudo -l", "patterns": ["sudo\\s+-l"], "explanation": "''sudo -l'' liệt kê binary chạy được qua sudo → tra GTFOBins xem binary đó có cách spawn shell/đọc-ghi file quyền root."}, {"prompt": "Loại file đặc biệt nào trên Linux, khi được set một bit quyền nhất định, sẽ luôn chạy với quyền của chủ sở hữu file (thường là root) bất kể ai thực thi nó, và đây là mục tiêu cần rà soát trong quá trình leo thang đặc quyền?", "patterns": ["suid"], "explanation": "File có bit SUID sẽ thực thi với quyền của owner (thường root) chứ không phải quyền người chạy; tìm các binary SUID bất thường rồi đối chiếu GTFOBins là kỹ thuật phổ biến.", "hint": "Bit quyền đặc biệt (Set User ID) trên Linux, thường tìm bằng lệnh find kèm -perm."}, {"prompt": "Kiểm tra các cron job hệ thống (chạy định kỳ, thường quyền root) để tìm script mà user ghi được. Gõ lệnh xem crontab hệ thống.", "hint": "cat /etc/crontab", "patterns": ["cat\\s+/etc/crontab", "/etc/cron", "crontab\\s+-l"], "explanation": "Xem /etc/crontab và /etc/cron.*; nếu một script chạy bằng root mà bạn ghi được → chèn reverse shell vào script đó."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Linux PrivEsc"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Linux PrivEsc';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Blue\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Ở bước quét ban đầu trên máy mục tiêu Windows trong room Blue, loại script Nmap nào được dùng để tự động phát hiện các dịch vụ có lỗ hổng đã biết (bao gồm lỗ hổng SMB)?", "patterns": ["vuln", "--script\\s*vuln", "nmap.*vuln"], "explanation": "Chạy Nmap với nhóm script ''vuln'' (--script vuln) giúp tự động đối chiếu dịch vụ phát hiện được với các lỗ hổng đã biết, từ đó lộ ra dịch vụ SMB dính MS17-010.", "hint": "Nmap có một nhóm NSE script chuyên dò lỗ hổng, tên nhóm chỉ gồm 4 chữ."}, {"prompt": "Xác nhận máy dính MS17-010 (EternalBlue) bằng nmap NSE trước khi khai thác. Gõ lệnh.", "hint": "nmap -p445 --script smb-vuln-ms17-010 <target>", "patterns": ["nmap.*smb-vuln", "smb-vuln-ms17-010"], "explanation": "Script báo VULNERABLE → khai thác bằng Metasploit ''exploit/windows/smb/ms17_010_eternalblue''."}, {"prompt": "Sau khi có được một shell cơ bản (ví dụ reverse shell) từ exploit MS17-010, Metasploit cung cấp module post-exploitation nào để nâng cấp shell đó thành một session mạnh hơn, hỗ trợ nhiều lệnh và module hậu khai thác hơn?", "patterns": ["meterpreter", "shell_to_meterpreter", "sessions.*upgrade"], "explanation": "Metasploit có module chuyển đổi shell thường thành session Meterpreter, cung cấp nhiều tính năng hậu khai thác như migrate, hashdump, file search...", "hint": "Đây là loại payload/session đặc trưng của Metasploit Framework, mạnh hơn shell thường."}, {"prompt": "Vì tiến trình khai thác ban đầu có thể không ổn định hoặc không chạy ở quyền SYSTEM thực sự, kỹ thuật nào trong Meterpreter cho phép chuyển session sang chạy bên trong một tiến trình hệ thống ổn định hơn (ví dụ services.exe)?", "patterns": ["migrate"], "explanation": "Lệnh migrate trong Meterpreter cho phép di chuyển session sang một process ID khác đang chạy với quyền cao và ổn định hơn, tránh mất session khi process ban đầu bị tắt.", "hint": "Lệnh Meterpreter dùng để ''di cư'' sang tiến trình khác, tên tiếng Anh nghĩa là di trú."}, {"prompt": "Sau khi có quyền SYSTEM, kỹ thuật nào được dùng để trích xuất các mật khẩu dạng hash (NTLM) từ cơ sở dữ liệu tài khoản local, và công cụ offline nào thường dùng để bẻ (crack) các hash đó bằng wordlist?", "patterns": ["hashdump", "john( the ripper)?"], "explanation": "Lệnh hashdump trong Meterpreter trích xuất hash NTLM từ SAM database; John the Ripper (với wordlist như rockyou.txt và định dạng NT) dùng để crack các hash này offline.", "hint": "Một lệnh Meterpreter để ''đổ'' hash, và một công cụ crack hash kinh điển mang tên ''Ripper''."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Blue"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Blue';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Web Application Pentesting (learning path chính thức)\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Kiểm thử SSTI: gửi biểu thức toán học vào tham số để xem template engine có thực thi không. Gõ lệnh curl.", "hint": "curl \"http://target/page?name={{7*7}}\"", "patterns": ["\\{\\{7\\*7\\}\\}", "curl.*7\\*7"], "explanation": "Nếu phản hồi trả 49 → input bị template engine (Jinja2/Twig) thực thi = SSTI, tiến tới RCE."}, {"prompt": "Kiểm thử XXE đọc /etc/passwd bằng cách gửi XML có external entity. Gõ lệnh curl POST.", "hint": "curl -X POST http://target/api -H \"Content-Type: application/xml\" --data ''<?xml version=\"1.0\"?><!DOCTYPE r [<!ENTITY x SYSTEM \"file:///etc/passwd\">]><r>&x;</r>''", "patterns": ["<!ENTITY", "file:///etc/passwd", "SYSTEM"], "explanation": "Định nghĩa ENTITY trỏ file:///etc/passwd rồi tham chiếu &x; → server nhúng nội dung file vào response = XXE."}, {"prompt": "Khai thác SSRF ép server gọi tới endpoint nội bộ (vd metadata cloud). Gõ lệnh curl.", "hint": "curl \"http://target/fetch?url=http://169.254.169.254/latest/meta-data/\"", "patterns": ["169\\.254\\.169\\.254", "url=http"], "explanation": "Ép tham số url trỏ về 127.0.0.1 / 169.254.169.254 → đọc dịch vụ nội bộ hoặc metadata (có thể lộ credential cloud)."}, {"prompt": "Kỹ thuật nào khiến server bị ép gửi request đến một địa chỉ/nội bộ do kẻ tấn công chỉ định (ví dụ để truy cập metadata service nội bộ hoặc dịch vụ chỉ cho phép localhost)?", "patterns": ["ssrf", "server[- ]?side request forgery"], "explanation": "SSRF (Server-Side Request Forgery) lợi dụng server thực hiện request thay cho kẻ tấn công tới tài nguyên nội bộ mà bình thường không thể truy cập từ ngoài.", "hint": "Viết tắt 4 chữ, trong đó có từ ''request forgery''."}, {"prompt": "Khi hai thiết bị trung gian (ví dụ load balancer và backend) hiểu sai lệch nhau về ranh giới của một request HTTP (do Content-Length/Transfer-Encoding), dẫn đến chèn request độc hại vào luồng của người dùng khác, đây là kỹ thuật gì?", "patterns": ["http\\s*smuggling", "request smuggling"], "explanation": "HTTP Request Smuggling khai thác sự khác biệt trong cách các tầng xử lý header Content-Length/Transfer-Encoding, cho phép ''giấu'' một request trong request khác.", "hint": "Kỹ thuật ''lậu'' request HTTP qua các tầng proxy/backend không đồng nhất cách parse."}], "difficulty": "co_ban", "cert_tags": ["THM WEB1"], "challenge_key": "THM:Web Application Pentesting (learning path chính thức)"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Web Application Pentesting (learning path chính thức)';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"RabbitStore\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Khai thác tính năng ''tải nội dung từ URL'' để SSRF quét cổng nội bộ (vd cổng quản trị RabbitMQ 15672). Gõ lệnh curl.", "hint": "curl \"http://target/api/fetch?url=http://127.0.0.1:15672/\"", "patterns": ["127\\.0\\.0\\.1", "url=http", "15672"], "explanation": "Ép server tự gọi 127.0.0.1:<port> → lộ dịch vụ nội bộ không expose ra ngoài."}, {"prompt": "Khai thác Mass Assignment: khi đăng ký, thêm field ẩn (vd plan/role/is_admin) vào JSON để nâng quyền. Gõ lệnh curl POST.", "hint": "curl -X POST http://target/api/register -H \"Content-Type: application/json\" --data ''{\"username\":\"x\",\"password\":\"y\",\"plan\":\"premium\"}''", "patterns": ["\"plan\"|is_admin|\"role\"", "--data|-d\\s"], "explanation": "Server gán mọi field trong body vào model → thêm trường không có trên UI (plan/role) để tự nâng cấp quyền."}, {"prompt": "Kiểm thử SSTI trên chatbot: gửi biểu thức để template engine thực thi. Gõ payload kiểm tra.", "hint": "{{7*7}}", "patterns": ["\\{\\{7\\*7\\}\\}"], "explanation": "Trả 49 = Jinja2 SSTI; nâng lên RCE bằng payload __globals__ ... popen(''id'')."}, {"prompt": "Sau khi có shell, đọc Erlang cookie của RabbitMQ để dùng cho RCE giữa các node. Gõ lệnh đọc cookie.", "hint": "cat /var/lib/rabbitmq/.erlang.cookie", "patterns": ["\\.erlang\\.cookie", "cat\\s+.*erlang"], "explanation": "Erlang cookie là bí mật xác thực giữa node; có nó thì dùng ''erl -setcookie'' / rabbitmqctl kết nối node để chạy lệnh (RCE)."}, {"prompt": "Sau khi có quyền quản trị RabbitMQ, bạn dùng API quản trị HTTP của RabbitMQ để lấy danh sách user, trong đó có password hash của user root được lưu ở dạng base64 chứa salt + hash. Để lấy được giá trị hash chuẩn (ví dụ SHA-256) từ dữ liệu này, bạn cần thực hiện bước xử lý nào?", "patterns": ["base64", "decode", "hex", "salt"], "explanation": "Cần decode chuỗi base64 thành dữ liệu hex/binary, sau đó loại bỏ phần salt ở đầu để lấy đúng giá trị hash chuẩn có thể tra cứu hoặc so khớp.", "hint": "Liên quan tới việc giải mã base64 rồi cắt bỏ phần salt phía trước hash."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1", "THM WEB1"], "challenge_key": "THM:RabbitStore"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — RabbitStore';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Silver Platter\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "App chạy trên cổng lạ (vd 8080) có CVE auth bypass. Dùng searchsploit tra PoC theo tên/phiên bản app. Gõ lệnh.", "hint": "searchsploit <ten_app> <version>", "patterns": ["searchsploit"], "explanation": "searchsploit tìm PoC offline từ Exploit-DB; auth bypass thường là thêm/sửa tham số để bỏ qua kiểm tra đăng nhập."}, {"prompt": "Khai thác IDOR: đổi ID trong URL/API để đọc tin nhắn của user khác. Gõ lệnh curl với ID khác.", "hint": "curl \"http://target/api/messages/1025\" -H \"Cookie: session=<token>\"", "patterns": ["messages/\\d+|/\\d{3,}", "curl"], "explanation": "ID tuần tự + không kiểm tra quyền sở hữu = IDOR; lặp ID (1024,1025...) để rút dữ liệu user khác."}, {"prompt": "Một hướng khai thác khác là brute-force mật khẩu đăng nhập. Bạn dùng công cụ sinh wordlist từ nội dung văn bản trên chính trang web mục tiêu, sau đó dùng công cụ fuzzing HTTP để thử các mật khẩu đó vào endpoint đăng nhập, lọc kết quả theo độ dài response. Tên hai công cụ này là gì?", "patterns": ["cewl", "ffuf"], "explanation": "CeWL tạo wordlist tùy biến từ nội dung text của website (thường chứa từ ngữ đặc trưng của tổ chức), còn ffuf dùng để fuzz các giá trị đó vào request đăng nhập và phân biệt thành công/thất bại qua kích thước response.", "hint": "Một công cụ sinh wordlist từ web content, một công cụ fuzzing HTTP nhanh viết bằng Go."}, {"prompt": "Leo quyền: user thuộc group ''adm'' đọc được /var/log. Tìm mật khẩu lộ trong log. Gõ lệnh grep.", "hint": "grep -riE \"password|passwd|cred\" /var/log/ 2>/dev/null", "patterns": ["grep.*-\\w*r.*(password|cred)", "/var/log"], "explanation": "Mật khẩu truyền qua command-line hay bị ghi vào log (auth.log, syslog); group adm đọc được → nhặt credential."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1"], "challenge_key": "THM:Silver Platter"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Silver Platter';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Avenger\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Bạn có danh sách tên nhân viên thật của tổ chức và muốn sinh ra các username khả dĩ theo quy ước đặt tên doanh nghiệp phổ biến (ví dụ tên.họ, họ_tên viết tắt), sau đó xác thực từng username với dịch vụ Kerberos để biết username nào thật sự tồn tại trong domain. Công cụ dùng để xác thực username qua Kerberos theo cách này gọi là gì?", "patterns": ["kerbrute"], "explanation": "Kerbrute cho phép kiểm tra username hợp lệ bằng cách gửi yêu cầu pre-authentication Kerberos (AS-REQ) và quan sát phản hồi khác nhau giữa username tồn tại và không tồn tại, không cần biết mật khẩu.", "hint": "Công cụ chuyên dò username hợp lệ qua giao thức Kerberos."}, {"prompt": "Sau khi xác thực được domain user bằng mật khẩu tái sử dụng từ máy khác, bạn muốn thu thập toàn bộ cấu trúc quan hệ, nhóm và quyền trong Active Directory (ai có quyền gì trên ai) để tìm đường leo thang. Công cụ/kỹ thuật chuyên dùng để visualize và phân tích quan hệ AD này là gì?", "patterns": ["bloodhound"], "explanation": "BloodHound (thu thập dữ liệu bằng bloodhound-python hoặc SharpHound) dựng đồ thị quan hệ AD, giúp phát hiện các đường leo thang quyền như quyền GenericAll, DCSync, thành viên nhóm lồng nhau.", "hint": "Công cụ dựng đồ thị quan hệ Active Directory để tìm đường leo thang quyền."}, {"prompt": "BloodHound cho thấy bạn có GenericAll trên một user AD. Lợi dụng để ĐẶT LẠI mật khẩu user đó (từ Kali). Gõ lệnh net rpc.", "hint": "net rpc password \"victim_user\" \"Newpass123!\" -U \"corp.local/me%mypass\" -S 10.10.10.1", "patterns": ["net rpc password", "bloodyAD", "Set-DomainUserPassword"], "explanation": "GenericAll = toàn quyền trên object → đặt lại mật khẩu victim (net rpc password / bloodyAD / PowerView Set-DomainUserPassword) rồi đăng nhập bằng user đó."}, {"prompt": "Bạn có SeBackupPrivilege → đọc được file bị khoá. Dump SAM & SYSTEM để lấy hash. Gõ lệnh reg save.", "hint": "reg save HKLM\\SAM C:\\temp\\sam.hive & reg save HKLM\\SYSTEM C:\\temp\\system.hive", "patterns": ["reg save", "diskshadow", "robocopy.*/b"], "explanation": "SeBackupPrivilege bỏ qua ACL khi đọc → reg save SAM/SYSTEM (hoặc diskshadow copy NTDS.dit) rồi secretsdump để lấy hash."}, {"prompt": "Sau khi lấy được ntds.dit và SYSTEM hive, bạn dùng công cụ nào (thuộc bộ Impacket) để trích xuất offline toàn bộ NTLM hash của các tài khoản domain, bao gồm cả Administrator?", "patterns": ["secretsdump"], "explanation": "secretsdump.py của Impacket có thể phân tích ntds.dit cùng SYSTEM hive để dump toàn bộ NTLM hash của domain mà không cần đăng nhập trực tiếp vào DC.", "hint": "Script trong bộ Impacket chuyên dump hash từ ntds.dit/SAM/SYSTEM."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1"], "challenge_key": "THM:Avenger"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Avenger';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"K2\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trong giai đoạn đầu enumeration, bạn chạy một công cụ quét cổng nhanh (nhanh hơn nmap mặc định) để phát hiện toàn bộ cổng mở trước khi chạy nmap với các script chi tiết (-A -sC). Tên công cụ quét cổng nhanh này thường dùng kết hợp với nmap là gì?", "patterns": ["rustscan"], "explanation": "RustScan quét toàn bộ 65535 cổng rất nhanh bằng cách tận dụng xử lý song song, sau đó có thể pipe kết quả cổng mở sang nmap để chạy script version/vulnerability detection chi tiết hơn.", "hint": "Công cụ quét cổng viết bằng Rust, nổi tiếng về tốc độ, thường kết hợp pipe sang nmap."}, {"prompt": "Trang lỗi do virtual host chưa khai báo. Thêm ánh xạ domain→IP vào file hosts cục bộ. Gõ lệnh.", "hint": "echo \"10.10.10.5 k2.thm\" | sudo tee -a /etc/hosts", "patterns": ["/etc/hosts", "tee\\s+-a\\s+/etc/hosts"], "explanation": "Thêm ''IP tên-miền'' vào /etc/hosts để trình duyệt/công cụ gửi đúng Host header, truy cập được vhost."}, {"prompt": "Sau khi xác định site là WordPress, bạn dùng một công cụ chuyên dụng để enumerate plugin, theme và phiên bản, từ đó phát hiện plugin Forminator đang ở phiên bản cũ có lỗ hổng. Tên công cụ enumerate WordPress này là gì?", "patterns": ["wpscan"], "explanation": "WPScan là công cụ chuyên dùng để quét WordPress, phát hiện plugin/theme đã cài, phiên bản của chúng, và đối chiếu với database lỗ hổng công khai.", "hint": "Công cụ CLI chuyên biệt để quét site WordPress tìm plugin/theme lỗ hổng."}, {"prompt": "Plugin Forminator cũ cho upload file bất kỳ không cần auth. Upload webshell qua form. Gõ lệnh curl.", "hint": "curl -F \"file=@shell.php\" \"http://target/wp-content/uploads/forminator/shell.php\"", "patterns": ["curl.*-F", "file=@", "\\.php"], "explanation": "Unrestricted file upload: gửi shell.php qua endpoint upload rồi truy cập đường dẫn đã upload để RCE."}, {"prompt": "Sau khi có web shell với quyền SYSTEM trên máy Windows, bạn dùng lệnh Windows nào để export (dump) registry hive SAM và SYSTEM ra file, nhằm sau đó trích xuất NTLM hash offline bằng Impacket secretsdump?", "patterns": ["reg save"], "explanation": "Lệnh `reg save` cho phép xuất một registry hive (ví dụ SAM, SYSTEM) ra file ngoài, sau đó các file này được dùng với secretsdump.py (offline mode) để trích xuất NTLM hash của các local account.", "hint": "Lệnh Windows built-in để lưu một registry hive ra file."}, {"prompt": "Có NTLM hash của Administrator nhưng chưa crack. Đăng nhập WinRM bằng chính hash (Pass-the-Hash). Gõ lệnh.", "hint": "evil-winrm -i 10.10.10.5 -u Administrator -H <NTLM_hash>", "patterns": ["evil-winrm.*-H", "-H\\s+[A-Fa-f0-9]{16,}", "pass.*the.*hash"], "explanation": "PtH: dịch vụ chấp nhận NTLM hash thay mật khẩu; evil-winrm/netexec -H <hash> để vào mà không cần crack."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1"], "challenge_key": "THM:K2"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — K2';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Ledger\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Để kiểm tra lỗ hổng kiểm soát truy cập trên một tính năng xem hồ sơ/đơn hàng theo ID (ví dụ /invoice/1024), phương pháp test có hệ thống nhất là gì: tạo 1 tài khoản rồi đoán ID, hay làm theo cách khác?", "patterns": ["2\\s*t[àa]i\\s*kho[ảa]n", "a\\s*/\\s*b", "tài khoản a.*tài khoản b"], "explanation": "Cách test chuẩn là tạo 2 tài khoản A và B, lấy ID tài nguyên của A, rồi dùng session của B gọi API với ID đó — nếu B xem/sửa được dữ liệu của A nghĩa là có lỗi kiểm soát truy cập (IDOR), tránh nhầm với việc chỉ đoán ID ngẫu nhiên trên 1 tài khoản.", "hint": "Cần ít nhất 2 tài khoản khác nhau để chứng minh được lỗi, không chỉ 1 tài khoản."}, {"prompt": "ID tài nguyên là số tăng dần → thử IDOR đọc hồ sơ user khác. Gõ lệnh curl đổi ID.", "hint": "curl \"http://target/api/users/1025\" -H \"Authorization: Bearer <token>\"", "patterns": ["/\\d{3,}", "curl"], "explanation": "Đổi ID tuần tự (1024→1025...) mà server không kiểm tra quyền sở hữu = IDOR."}, {"prompt": "Request cập nhật hồ sơ có thể nhận thêm field ẩn (role/is_admin). Khai thác Mass Assignment. Gõ lệnh curl POST.", "hint": "curl -X POST http://target/api/profile -H \"Content-Type: application/json\" --data ''{\"name\":\"x\",\"role\":\"admin\"}''", "patterns": ["\"role\"|is_admin", "--data|-d\\s"], "explanation": "Thêm trường role/is_admin vào body; server gán hết → tự nâng quyền."}, {"prompt": "Sau khi đăng nhập thành công, nếu bạn thay đổi giá trị của cookie/token session (ví dụ sửa 1 ký tự hoặc decode rồi sửa payload của JWT) và server vẫn chấp nhận với quyền cao hơn, lỗ hổng xác thực này liên quan tới điều gì?", "patterns": ["jwt", "token.*(không.*k[iý] |không verify)", "signature", "x[áa]c\\s*th[ựu]c\\s*token"], "explanation": "Đây là lỗi xác thực token/session: nếu server không verify đúng chữ ký (signature) của JWT hoặc không kiểm tra tính toàn vẹn của session token, kẻ tấn công có thể tự sửa claim (ví dụ role, user id) để leo quyền.", "hint": "Liên quan tới việc server không kiểm tra đủ chặt tính hợp lệ của token sau khi bị chỉnh sửa."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Ledger"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Ledger';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Billing\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Dirbuster không ra gì → kiểm tra robots.txt tìm đường dẫn ẩn (vd app billing VoIP). Gõ lệnh curl.", "hint": "curl http://target/robots.txt", "patterns": ["robots\\.txt", "curl.*robots"], "explanation": "robots.txt liệt kê path mà admin muốn giấu khỏi search engine → thường lộ thư mục/ứng dụng ẩn để tấn công tiếp."}, {"prompt": "Bạn xác định ứng dụng billing đang chạy có một mã CVE công khai cho phép thực thi lệnh từ xa không cần xác thực (unauthenticated RCE). Công cụ khai thác tự động nào thường được dùng để tìm và chạy module khai thác sẵn có cho CVE như vậy?", "patterns": ["metasploit", "msfconsole"], "explanation": "Metasploit Framework chứa sẵn nhiều module khai thác cho các CVE phổ biến; chỉ cần set đúng target, RHOSTS và các option rồi chạy exploit để lấy shell.", "hint": "Framework khai thác nổi tiếng với các module exploit có sẵn, dùng msfconsole."}, {"prompt": "Sau khi có shell với quyền thấp, bạn chạy lệnh để kiểm tra user hiện tại có quyền chạy chương trình nào với sudo mà không cần mật khẩu. Lệnh đó là gì?", "patterns": ["sudo -l", "sudo l"], "explanation": "`sudo -l` liệt kê các lệnh user hiện tại được phép chạy bằng sudo, đây là bước kiểm tra privilege escalation kinh điển trên Linux.", "hint": "Lệnh sudo với flag viết thường ''l'' để liệt kê quyền."}, {"prompt": "Bạn phát hiện user được phép chạy fail2ban-client bằng sudo không cần mật khẩu. Fail2Ban cho phép cấu hình ''action'' tùy chỉnh chạy khi một IP bị ban. Kỹ thuật lợi dụng tính năng này để chạy lệnh với quyền root được gọi là gì?", "patterns": ["fail2ban", "custom action", "ban action abuse"], "explanation": "Fail2Ban chạy các action (thường là shell command) với quyền root khi một jail kích hoạt ban; nếu attacker có quyền sửa cấu hình action, họ có thể chèn lệnh tùy ý để thực thi với quyền root khi ban được trigger.", "hint": "Liên quan tới việc sửa action của jail (ví dụ sshd) trong Fail2Ban để chạy lệnh tùy chỉnh."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1"], "challenge_key": "THM:Billing"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Billing';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Sweettooth Inc.\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Phát hiện InfluxDB (time-series DB) phiên bản cũ dính auth bypass. Truy vấn không cần xác thực để liệt kê database. Gõ lệnh curl.", "hint": "curl \"http://target:8086/query?q=SHOW+DATABASES\"", "patterns": [":8086", "SHOW\\s+DATABASES|/query"], "explanation": "InfluxDB < 1.7.6 dính CVE-2019-20933 (JWT auth bypass) → truy vấn /query không cần auth, SHOW DATABASES để lấy dữ liệu."}, {"prompt": "Lỗ hổng cho phép tạo một token xác thực giả (ví dụ dùng jwt.io với secret để trống và username bị lộ qua endpoint debug) để được InfluxDB chấp nhận như đã đăng nhập hợp lệ. Loại token/kỹ thuật giả mạo xác thực này gọi là gì?", "patterns": ["jwt", "json\\s*web\\s*token", "auth(entication)?\\s*bypass"], "explanation": "JWT (JSON Web Token) forgery: khi secret dùng để ký token để trống hoặc dễ đoán, kẻ tấn công có thể tự tạo (forge) một JWT hợp lệ với username lấy được từ endpoint rò rỉ thông tin, qua đó bypass xác thực của InfluxDB.", "hint": "Đây là loại token JSON dùng để xác thực API, có thể bị giả mạo nếu secret ký yếu hoặc rỗng."}, {"prompt": "Sau khi có quyền truy cập SSH vào container và phát hiện Docker Engine API đang lắng nghe cục bộ (ví dụ cổng 8080), kẻ tấn công tạo một container mới có bind-mount toàn bộ filesystem gốc của host vào trong, rồi exec để chạy shell với quyền privileged. Kỹ thuật này gọi là gì?", "patterns": ["container\\s*escape", "docker\\s*escape", "privileged\\s*container"], "explanation": "Đây là kỹ thuật container escape qua Docker Engine API: bằng cách tạo container mới bind-mount ''/'' của host và chạy ở chế độ privileged, kẻ tấn công thoát ra khỏi container ban đầu và có toàn quyền đọc/ghi trên hệ thống host.", "hint": "Kỹ thuật này giúp ''thoát'' khỏi container Docker để chiếm quyền trên máy chủ thật (host)."}], "difficulty": "trung_binh", "cert_tags": ["THM WEB1"], "challenge_key": "THM:Sweettooth Inc."}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Sweettooth Inc.';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Loopback\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Sau khi quét toàn bộ cổng bằng nmap và thấy các cổng HTTP/HTTPS cùng RDP đang mở, bước tiếp theo để tìm các đường dẫn/thư mục ẩn trên web server (ví dụ phát hiện ra đường dẫn /ecp của Exchange) là dùng loại công cụ gì?", "patterns": ["gobuster", "dirbuster", "ffuf", "dirb", "directory\\s*(brute|fuzz)"], "explanation": "Gobuster (hoặc ffuf/dirbuster) dùng để brute-force các đường dẫn/thư mục ẩn trên web server bằng wordlist, giúp phát hiện các endpoint quản trị như /ecp (Exchange Control Panel) mà không được liệt kê công khai.", "hint": "Công cụ dò thư mục web bằng wordlist, thường dùng cùng SecLists."}, {"prompt": "Đường dẫn /ecp là dấu hiệu đặc trưng của một ứng dụng mail server phổ biến của Microsoft. Ứng dụng đó tên là gì?", "patterns": ["exchange", "microsoft\\s*exchange", "owa"], "explanation": "/ecp (Exchange Control Panel) và /owa (Outlook Web Access) là các endpoint đặc trưng của Microsoft Exchange Server, một mục tiêu phổ biến cho các lỗ hổng pre-auth RCE nổi tiếng.", "hint": "Đây là phần mềm email server của Microsoft, nổi tiếng với lỗ hổng ProxyShell/ProxyLogon."}, {"prompt": "Một tính năng trên web portal (ví dụ liên quan BitLocker) cho phép nhập đường dẫn, nhưng ứng dụng không lọc kỹ đầu vào nên kẻ tấn công có thể chèn thêm lệnh hệ thống (ví dụ dir, type) để thực thi trên server. Lớp lỗ hổng này gọi là gì?", "patterns": ["command\\s*injection", "os\\s*command\\s*injection", "ch[èe]n\\s*l[ệe]nh"], "explanation": "Command injection (chèn lệnh hệ thống) xảy ra khi input của người dùng được nối trực tiếp vào lệnh shell/PowerShell mà không được validate, cho phép kẻ tấn công thực thi lệnh tùy ý như liệt kê thư mục hoặc đọc file.", "hint": "Lỗ hổng cho phép chạy thêm lệnh OS thông qua một trường input của web app."}, {"prompt": "Nghi Exchange chưa vá ProxyShell. Thăm dò bằng request autodiscover (SSRF ProxyShell). Gõ lệnh curl.", "hint": "curl -ks \"https://target/autodiscover/autodiscover.json?@evil.com/mapi/nspi/?&Email=autodiscover/autodiscover.json%3f@evil.com\"", "patterns": ["autodiscover", "proxyshell", "34473"], "explanation": "ProxyShell = chuỗi CVE-2021-34473/34523/31207 (pre-auth) trên Exchange 2021; probe autodiscover.json để xác nhận rồi khai thác lên RCE."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"], "challenge_key": "THM:Loopback"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Loopback';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Reset\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trong hầu hết các bài lab pentest dạng ''boot-to-root'' như room Reset, bước đầu tiên bắt buộc trước khi tấn công là gì, và công cụ phổ biến nhất để thực hiện bước đó là gì?", "patterns": ["nmap", "quét cổng", "port scan"], "explanation": "Bước đầu tiên luôn là quét cổng/dịch vụ (thường bằng Nmap) để biết máy mục tiêu đang chạy dịch vụ gì, từ đó xác định hướng tấn công tiếp theo.", "hint": "Công cụ dòng lệnh quét cổng và nhận diện dịch vụ phổ biến nhất."}, {"prompt": "Sau khi tìm thấy một dịch vụ web hoặc ứng dụng chạy trên máy mục tiêu, bước tiếp theo trong phương pháp luận pentest là gì trước khi thử khai thác bất kỳ lỗ hổng cụ thể nào?", "patterns": ["enum", "liệt kê", "dò thư mục", "gobuster", "dirbuster"], "explanation": "Cần tiếp tục enumeration (ví dụ dò thư mục/endpoint bằng Gobuster, kiểm tra phiên bản phần mềm, tìm thông tin nhạy cảm) để hiểu rõ bề mặt tấn công trước khi khai thác.", "hint": "Giai đoạn ''thu thập thông tin sâu hơn'' sau khi đã biết dịch vụ đang chạy là gì."}, {"prompt": "Sau initial access quyền thấp, liệt kê đặc quyền hiện tại để tìm đường leo quyền. Gõ lệnh (Windows).", "hint": "whoami /priv", "patterns": ["whoami\\s+/priv", "sudo\\s+-l"], "explanation": "Mục tiêu giai đoạn sau là privilege escalation; bắt đầu bằng liệt kê quyền (whoami /priv trên Windows, sudo -l trên Linux)."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Reset"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Reset';

UPDATE cards SET payload = '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Jr Penetration Tester (learning path chính thức)\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trong giai đoạn trinh sát (reconnaissance) của lộ trình Jr Penetration Tester, công cụ nào được dùng để khám phá host, cổng dịch vụ đang mở và chạy script dò lỗ hổng (vulnerability scripting)?", "patterns": ["nmap"], "explanation": "Nmap là công cụ quét mạng chủ đạo, cho phép dò cổng, nhận diện dịch vụ/phiên bản (-sV) và chạy các script NSE để phát hiện lỗ hổng đã biết.", "hint": "Công cụ dòng lệnh quét cổng và dịch vụ phổ biến nhất trong pentest."}, {"prompt": "Để tự động hóa tấn công brute-force vào form đăng nhập web hoặc dịch vụ mạng (SSH, FTP...) trong lộ trình này, công cụ nào thường được sử dụng?", "patterns": ["hydra"], "explanation": "Hydra là công cụ brute-force đa năng, hỗ trợ nhiều giao thức (HTTP form, SSH, FTP, RDP...) để dò mật khẩu bằng wordlist.", "hint": "Công cụ brute-force nổi tiếng của THC, tên loài quái vật nhiều đầu."}, {"prompt": "Khi đã xác định được phiên bản phần mềm/dịch vụ trên máy mục tiêu, kỹ thuật/công cụ nào giúp tra cứu nhanh các exploit công khai đã biết cho phiên bản đó ngay trên terminal?", "patterns": ["searchsploit", "exploit[- ]?db"], "explanation": "Searchsploit (bản offline của Exploit-DB) cho phép tìm kiếm exploit theo tên phần mềm/phiên bản mà không cần lên mạng.", "hint": "Công cụ dòng lệnh đi kèm Exploit-DB, dùng để tìm PoC/exploit có sẵn."}, {"prompt": "Module privesc của lộ trình khai thác cấu hình sai. Bắt đầu bằng liệt kê quyền để tìm misconfig. Gõ lệnh (Linux).", "hint": "sudo -l", "patterns": ["sudo\\s+-l", "whoami\\s+/priv"], "explanation": "Privesc trong PT1 chủ yếu là misconfig (sudo, SUID, service, quyền file); ''sudo -l'' / ''whoami /priv'' là bước liệt kê đầu tiên."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Jr Penetration Tester (learning path chính thức)"}'::jsonb
FROM decks d, subjects s
WHERE cards.deck_id = d.id AND d.subject_id = s.id
  AND s.slug = 'pentest' AND d.slug = 'labs' AND cards.front = '[Simulation] THM — Jr Penetration Tester (learning path chính thức)';
